// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;
    address nonOwner;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 valueToDeposit, uint256 withdrawAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= valueToDeposit);
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint beforeBal = address(c).balance;
        vm.assume(true);
        address ownerAddr;
        try c.owner() returns (address __r) { ownerAddr = __r; } catch { return; }
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        uint afterBal = address(c).balance;
        assertTrue(((ownerAddr != address(this)) ? withdrawReverted : (afterCount == beforeCount)));
    }

    function testFuzz_run(uint256 valueToDeposit, uint256 withdrawAmount) public {
        _run(valueToDeposit, withdrawAmount);
    }

    receive() external payable {}
}
